<?php
declare(strict_types=1);session_start();require_once __DIR__.'/config.php';if($_SERVER['REQUEST_METHOD']!=='POST'){header('Location:index.php');exit;}$nick=trim($_POST['nick']??'');$senha=(string)($_POST['senha']??'');if($nick===''||$senha===''){$_SESSION['login_error']='Preencha o Nick e a senha.';header('Location:index.php');exit;}try{$pdo=db();$sql='SELECT * FROM '.GAME_TABLE.' WHERE '.GAME_NAME_COLUMN.'=:nick LIMIT 1';$st=$pdo->prepare($sql);$st->execute([':nick'=>$nick]);$p=$st->fetch();if(!$p){$_SESSION['login_error']='Nick ou senha incorretos.';header('Location:index.php');exit;}$stored=(string)($p[GAME_PASSWORD_COLUMN]??'');$ok=$stored!==''&&(password_verify($senha,$stored)||hash_equals($stored,$senha));if(!$ok){$_SESSION['login_error']='Nick ou senha incorretos.';header('Location:index.php');exit;}session_regenerate_id(true);$_SESSION['player']=$p;header('Location:dashboard.php');exit;}catch(Throwable $e){error_log('UCP LOGIN ERROR: '.$e->getMessage());$_SESSION['login_error']='Não foi possível realizar o login.';header('Location:index.php');exit;}
